-- Exact scope semantics unchanged; avoid repeatedly materializing entire cache rows as JSON.
create or replace function operations_private.hub_input_scope_v1(p_sku text,p_source text)
returns text[] language plpgsql stable set search_path=pg_catalog as $scope$
declare codes text[]:=array[p_sku];next_codes text[];products text[];i integer;
begin
 if length(coalesce(p_sku,'')) not between 1 and 128 or p_source is null or p_source not in ('','smartstore','makeshop','ably') then raise exception 'invalid input scope';end if;
 for i in 1..64 loop
  products:=array[]::text[];
  if p_source<>'' then
   select coalesce(array_agg(distinct product),'{}') into products from(
    select case p_source when 'smartstore' then c.smartstore_product_code when 'makeshop' then c.makeshop_product_code when 'ably' then c.ably_product_code end product
    from operations_private.operations_hub_matrix_export_cache c where c.sellpia_sku_code=any(codes)
   ) group_keys where product is not null and product<>'';
  end if;
  select array_agg(distinct sku order by sku) into next_codes from(
   select unnest(codes) sku union
   select r.parent_sku from operations_private.hub_field_references r where r.child_sku=any(codes) union
   select c.sellpia_sku_code from operations_private.operations_hub_matrix_export_cache c
    where (p_source='smartstore' and c.smartstore_product_code=any(products))
     or (p_source='makeshop' and c.makeshop_product_code=any(products))
     or (p_source='ably' and c.ably_product_code=any(products))
  ) inputs;
  if cardinality(next_codes)>2000 then raise exception 'input dependency scope too large';end if;
  if next_codes=codes then return codes;end if;codes:=next_codes;
 end loop;
 raise exception 'input scope exceeds 64 expansion steps';
end $scope$;
revoke all on function operations_private.hub_input_scope_v1(text,text) from public,anon,authenticated;
